// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _test_seedMarket_initializes(uint256 drugs, uint256 eth) internal {
        eth = bound(eth, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(drugs > 0);
        vm.assume(eth > 0);
        vm.assume(address(this).balance >= eth);
        try c.seedMarket{value: eth}(drugs) {} catch { return; }
        assertTrue(c.initialized() == true);
    }

    function testFuzz_test_seedMarket_initializes(uint256 drugs, uint256 eth) public {
        _test_seedMarket_initializes(drugs, eth);
    }

    receive() external payable {}
}
